export async function verifyNativeCompanyAuditReports({db,profile,revision,secret}){
 const keys=['JWT_SECRET','MWS_STORE_LIFECYCLE_PROFILE','RENDER_GIT_COMMIT','BACKUP_MONITOR_SECRET'],saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));Object.assign(process.env,{JWT_SECRET:'isolated-native-company-audit-reports-secret',MWS_STORE_LIFECYCLE_PROFILE:`BACKOFFICE_COMPANY_${profile}_V1`,RENDER_GIT_COMMIT:revision,BACKUP_MONITOR_SECRET:secret});
 const write=fn=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return fn(tx)});
 const mutate=(sql,...values)=>write(tx=>tx.$executeRawUnsafe(sql,...values));
 const insert=(table,row,json=[])=>{const entries=Object.entries(row);return mutate(`INSERT INTO "${table}"(${entries.map(([k])=>'"'+k+'"').join(',')}) VALUES(${entries.map(([k],i)=>'$'+(i+1)+(json.includes(k)?'::jsonb':'')).join(',')})`,...entries.map(([k,v])=>json.includes(k)?JSON.stringify(v):v))};
 const at=new Date('2026-11-20T10:00:00Z');let server;
 try{
  await insert('User',{id:'native-audit-foreign-user',companyId:'foreign',email:'foreign-audit@native.invalid',passwordHash:'NOT_LOGIN',fullName:'FOREIGN_ACTOR_CANARY',updatedAt:at});
  for(const [id,cost]of [['unknown',null],['zero',0]]){await insert('Product',{id:'native-audit-product-'+id,companyId:'company',name:'Audit product '+id,salePrice:id==='zero'?0:10,costPrice:cost});await insert('StoreProduct',{id:'native-audit-stock-'+id,storeId:'selected',productId:'native-audit-product-'+id,currentStock:0})}
  for(const [id,companyId,storeId,productId]of [['zero','company','selected','native-audit-product-zero'],['bad-product','company','selected','foreign-item'],['global','company',null,'native-audit-product-unknown'],['sibling','company','sibling','native-audit-product-zero'],['foreign','foreign','foreign','foreign-item']])await insert('KioskAuditEvent',{id:'native-deactivate-'+id,companyId,storeId,productId,productName:'Native deactivated history',eventType:'PRODUCT_ACTIVE_CHANGE',oldActive:true,newActive:false,details:{secret:'RAW_AUDIT_CANARY'},createdAt:at},['details']);
  for(const [id,companyId,storeId,quantity,unitPrice]of [['known','company','selected',2,3],['unknown','company','sibling',null,null],['foreign','foreign','foreign',99,99]])await insert('KioskAuditEvent',{id:'native-delete-'+id,companyId,storeId,productId:'foreign-item',productName:'Native deleted historical',eventType:'SALE_LIST_DELETE',quantity,unitPrice,details:{secret:'RAW_AUDIT_CANARY'},createdAt:at},['details']);
  for(const [id,companyId,storeId,saleId,relatedSaleId,actionType,details]of [['zero-cart','company','selected',null,null,'CART_CANCEL',{items:[{productId:'foreign-item',productName:'Native zero cart',quantity:0,unitPrice:0,secret:'RAW_AUDIT_CANARY'}],sessionId:'RAW_AUDIT_CANARY'}],['priced-cart','company','sibling',null,null,'CART_ITEM_REMOVE',{productId:'foreign-item',productName:'Native priced cart',quantity:'2',unitPrice:'5.00',secret:'RAW_AUDIT_CANARY'}],['foreign-sale','company','selected','native-sale-foreign','native-sale-foreign','CANCEL',{secret:'RAW_AUDIT_CANARY'}],['wrong-store','company','sibling','native-sale-selected','native-sale-selected','RETURN',{secret:'RAW_AUDIT_CANARY'}],['delayed','company','selected','native-sale-selected',null,'DELAYED',{previousQuantity:0,newQuantity:1,oldOccurredAt:'2026-11-18T10:00:00Z',newOccurredAt:'2026-11-20T10:00:00Z',secret:'RAW_AUDIT_CANARY'}],['foreign','foreign','foreign','native-sale-foreign',null,'CANCEL',{secret:'RAW_AUDIT_CANARY'}]])await insert('PosSaleActionAudit',{id:'native-action-'+id,companyId,storeId,saleId,relatedSaleId,actionType,details,createdAt:at},['details']);
  for(const [id,companyId,storeId,productId,unitCost,quantity]of [['unknown','company','selected','native-audit-product-unknown',null,-2],['zero','company','sibling','native-audit-product-zero',0,0],['bad-product','company','selected','foreign-item',999,99],['foreign','foreign','foreign','foreign-item',999,99]])await insert('StockMovement',{id:'native-movement-'+id,storeId,productId,movementType:'ADJUSTMENT',quantity,unitCost,sourceId:'RAW_AUDIT_CANARY',createdByUserId:'native-audit-foreign-user',createdAt:at});
  for(const [id,companyId,storeId,productId,price]of [['unknown','company','selected','native-audit-product-unknown',-10],['zero','company','sibling','native-audit-product-zero',0],['foreign','foreign','foreign','foreign-item',-999]]){await insert('Sale',{id:'native-destruction-sale-'+id,companyId,storeId,source:'PRODUCT_DESTRUCTION',occurredAt:at});await insert('SaleLine',{id:'native-destruction-line-'+id,saleId:'native-destruction-sale-'+id,productId,description:'Native destruction history',quantity:-2,unitPrice:price,lineTotal:price*2})}
  for(const [id,userId]of [['own','staff'],['foreign','native-audit-foreign-user']])await insert('AuthAudit',{id:'native-login-'+id,userId,email:id+'@native.invalid',event:'LOGIN',success:true,deviceName:'Native displayed device',ipAddress:'203.0.113.77',userAgent:'RAW_AUDIT_CANARY',createdAt:at});
  const names=['deactivations','sale-deletions','pos-sale-actions','destructions','logins','movements'],caps=names.map(n=>'reports-'+n+'.read'),owner={id:'company-owner',companyId:'company',role:'OWNER',tokenType:'BACKOFFICE_USER',sessionId:'company-owner-session',sessionVersion:0};
  const created=await createStaffAccount(db,owner,{username:'company.audit.reports.native',fullName:'Company Audit Reports Native',pin:'987654',grants:[],companyCapabilities:caps});await insert('UserSession',{id:'native-audit-reports-session',userId:created.id,expiresAt:new Date(Date.now()+3600000)});assert.equal((await db.$queryRawUnsafe('SELECT 1 FROM "BackofficeStaffGrant" WHERE "userId"=$1',created.id)).length,0);
  let afterRead=null;const readDb=new Proxy(db,{get(target,key){if(['$executeRaw','$executeRawUnsafe','$transaction'].includes(key))return()=>assert.fail('native audit report attempted mutation/bootstrap');const value=target[key];if(key==='$queryRaw')return async(...args)=>{const sql=args[0].join('?');assert.doesNotMatch(sql,/\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|FOR UPDATE)\b/);const rows=await value.apply(target,args);if(afterRead&&/FROM "(?:KioskAuditEvent|PosSaleActionAudit|StockMovement|SaleLine|AuthAudit)"/.test(sql)){const action=afterRead;afterRead=null;await action()}return rows};return typeof value==='function'?value.bind(target):value}});
  const source=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8'),auth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',source.slice(source.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);
  const app=express();app.use(express.json());const index=await readFile(new URL('../../src/index.js',import.meta.url),'utf8'),start=index.indexOf('// Exact company reads precede'),end=index.indexOf('app.use("/api/management/vat-departments"',start);assert.ok(start>0&&end>start);new Function('app','auth','readStaffCompanyDirectory','prisma',index.slice(start,end))(app,auth,readStaffCompanyDirectory,readDb);app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_FALLTHROUGH'}));app.use((e,_req,res,_next)=>res.status(e.status||500).json({code:e.code}));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const claims={id:created.id,companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionVersion:0,sessionId:'native-audit-reports-session'},token=jwt.sign(claims,process.env.JWT_SECRET),range='from=2026-11-20&to=2026-11-20';
  const get=async(path,headers={})=>{const r=await fetch(`http://127.0.0.1:${server.address().port}/api/reports/${path}`,{headers:{authorization:'Bearer '+token,'x-backoffice-company-id':'company',...headers}});return {status:r.status,body:await r.json()}};
  const results={};for(const name of names){const r=await get(name+'?'+range);assert.equal(r.status,200,JSON.stringify({name,...r}));assert.equal(r.body.scope,'COMPANY');assert.doesNotMatch(JSON.stringify(r.body),/RAW_AUDIT_CANARY|FOREIGN_ACTOR_CANARY/);results[name]=r.body}
  const deactivated=results.deactivations;assert.equal(deactivated.count,4);const zero=deactivated.items.find(r=>r.id==='native-deactivate-zero');assert.equal(zero.salePrice,0);assert.equal(zero.currentStock,0);assert.equal(zero.incomplete,false);const bad=deactivated.items.find(r=>r.id==='native-deactivate-bad-product');assert.equal(bad.productId,null);assert.equal(bad.salePrice,null);assert.equal(bad.currentStock,null);assert.equal(bad.incomplete,true);assert.equal((await get('deactivations?'+range+'&storeId=selected')).body.count,3);
  const deleted=results['sale-deletions'];assert.equal(deleted.count,4);assert.equal(deleted.totalValue,null);assert.equal(deleted.incomplete,true);assert.equal(deleted.items.find(r=>r.id==='pos-native-action-zero-cart-0').lineTotal,0);assert.equal(deleted.items.find(r=>r.id==='pos-native-action-priced-cart-0').productId,null);assert.equal(deleted.items.find(r=>r.id==='pos-native-action-priced-cart-0').lineTotal,10);assert.equal(deleted.items.find(r=>r.id==='native-delete-known').productId,null);assert.equal(deleted.items.find(r=>r.id==='native-delete-known').lineTotal,6);
  const actions=results['pos-sale-actions'];assert.equal(actions.count,5);assert.deepEqual(actions.summary,{count:5,cancellations:1,returns:1,delayed:1});for(const id of ['foreign-sale','wrong-store']){const r=actions.items.find(r=>r.id==='native-action-'+id);assert.equal(r.saleId,null);assert.equal(r.relatedSaleId,null);assert.equal(r.saleTotal,null);assert.equal(r.customerName,null)}assert.equal(actions.items.find(r=>r.id==='native-action-delayed').auditDetails.previousQuantity,0);assert.ok(actions.items.every(r=>!Object.hasOwn(r,'details')&&!Object.hasOwn(r,'sessionId')));
  const movements=results.movements;assert.equal(movements.count,2);assert.equal(movements.items.find(r=>r.id==='native-movement-unknown').outQty,2);assert.equal(movements.items.find(r=>r.id==='native-movement-zero').unitCost,0);assert.ok(movements.items.every(r=>r.operatorName===null&&!Object.hasOwn(r,'sourceId')));
  const destroyed=results.destructions;assert.equal(destroyed.count,2);assert.equal(destroyed.totalPurchase,null);assert.equal(destroyed.incomplete,true);assert.equal(destroyed.items.find(r=>r.id==='native-destruction-line-zero').purchaseTotal,0);assert.equal(destroyed.items.find(r=>r.id==='native-destruction-line-unknown').purchasePrice,null);
  assert.equal(results.logins.count,1);assert.equal(results.logins.items[0].id,'native-login-own');assert.equal(results.logins.items[0].ipAddress,'203.0.113.77');assert.equal(Object.hasOwn(results.logins.items[0],'userAgent'),false);
  for(const path of ['logins?'+range+'&storeId=selected','movements?'+range+'&storeId=foreign','deactivations?'+range+'&unknown=1','sale-deletions?from=2026-02-30&to=2026-03-01'])assert.ok([400,403,404].includes((await get(path)).status));assert.equal((await get('movements?'+range,{'x-backoffice-store-id':'selected'})).status,403);
  await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');for(const name of names.slice(0,4))assert.equal((await get(name+'?'+range)).status,200);for(const name of names.slice(4))assert.equal((await get(name+'?'+range)).status,403);await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');
  await mutate('UPDATE "Company" SET "licenseStatus"=\'EXPIRED\' WHERE "id"=\'company\'');for(const name of names)assert.equal((await get(name+'?'+range)).status,403);await mutate('UPDATE "Company" SET "licenseStatus"=\'ACTIVE\' WHERE "id"=\'company\'');
  afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "revision"="revision"+1 WHERE "userId"=$1',created.id);assert.equal((await get('movements?'+range)).status,403);afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "companyCapabilities"=\'[]\'::jsonb WHERE "userId"=$1',created.id);assert.equal((await get('deactivations?'+range)).status,403);
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}for(const key of keys){if(saved[key]===undefined)delete process.env[key];else process.env[key]=saved[key]}}
}
